import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.CRfKVJQk.js";const u=JSON.parse('{"title":"08 · Predicted runtime behaviour (code trace)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/08-behaviour-trace.md","filePath":"architecture/08-behaviour-trace.md"}'),s={name:"architecture/08-behaviour-trace.md"};function o(i,t,n,l,h,c){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="_08-·-predicted-runtime-behaviour-code-trace" tabindex="-1">08 · Predicted runtime behaviour (code trace) <a class="header-anchor" href="#_08-·-predicted-runtime-behaviour-code-trace" aria-label="Permalink to &quot;08 · Predicted runtime behaviour (code trace)&quot;">​</a></h1><p>What the code will do at runtime, traced by reading it step by step. Use it to know what to expect on a device, and to spot the difference when a device disagrees.</p><p><strong>Confidence</strong>: 🟢 follows directly from code we compiled/tested · 🟡 depends on Android/iOS framework behaviour we could not run · 🔴 unverified guess.</p><hr><h2 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h2><h3 id="a1-·-screen-mounts-glassbackdrop-one-liquidglassview-on-top" tabindex="-1">A1 · Screen mounts (<code>GlassBackdrop</code> + one <code>LiquidGlassView</code> on top) <a class="header-anchor" href="#a1-·-screen-mounts-glassbackdrop-one-liquidglassview-on-top" aria-label="Permalink to &quot;A1 · Screen mounts (`GlassBackdrop` + one `LiquidGlassView` on top)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>What happens</th><th>Code</th><th>Conf.</th></tr></thead><tbody><tr><td>1</td><td>Fabric creates both views and applies props. Glass <code>commitConfig()</code> snaps (first commit, not attached)</td><td><code>LiquidGlassViewManager.onAfterUpdateTransaction</code></td><td>🟢</td></tr><tr><td>2</td><td>Backdrop attaches → registered. Glass attaches → registered, pre-draw listener added, <code>needsRebind = true</code></td><td><code>onAttachedToWindow</code></td><td>🟢</td></tr><tr><td>3</td><td>First frame, pre-draw: glass resolves the backdrop (same window, not an ancestor), enables recording on it (backdrop invalidates), picks a renderer (API 33+ → SHADER, compiles the AGSL once)</td><td><code>ensureBinding</code>, <code>ensureRenderer</code></td><td>🟢</td></tr><tr><td>4</td><td>Same frame, draw: the backdrop records its children into <code>contentNode</code> and draws it; then the glass draws the same node through blur → saturation → shader, then tint + border; children draw sharp on top</td><td><code>GlassBackdropView.draw</code>, <code>RenderNodeGlassRenderer.draw</code></td><td>🟡</td></tr><tr><td>5</td><td>If the glass is earlier in z-order than the backdrop, frame 1 shows the solid fallback and frame 2 shows glass</td><td><code>hasRecordedContent()</code> branch</td><td>🟢</td></tr></tbody></table><p><strong>Expected on screen:</strong> glass visible from the first or second frame. No flicker afterwards.</p><h3 id="a2-·-user-scrolls-a-list-inside-the-backdrop" tabindex="-1">A2 · User scrolls a list inside the backdrop <a class="header-anchor" href="#a2-·-user-scrolls-a-list-inside-the-backdrop" aria-label="Permalink to &quot;A2 · User scrolls a list inside the backdrop&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>What happens</th><th>Code</th><th>Conf.</th></tr></thead><tbody><tr><td>1</td><td>ScrollView invalidates → Android calls <code>onDescendantInvalidated</code> up the tree → backdrop bumps <code>contentVersion</code> and tells its glass views to invalidate</td><td><code>GlassBackdropView.onDescendantInvalidated</code>, <code>BackdropRegistry.notifyContentChanged</code></td><td>🟡</td></tr><tr><td>2</td><td>Same frame: the child re-records its own display list; <code>contentNode</code> references it, so the glass re-renders with the new content</td><td>RenderNode references</td><td>🟡</td></tr><tr><td>3</td><td>Cost per frame: 1 blur + shader pass per glass over its sample area</td><td>—</td><td>🟢</td></tr></tbody></table><p><strong>Expected:</strong> blur follows the list with no lag. GPU busy while scrolling, idle when stopped.</p><h3 id="a3-·-glass-moves-animated-reanimated-scrolls-itself" tabindex="-1">A3 · Glass moves (Animated / Reanimated / scrolls itself) <a class="header-anchor" href="#a3-·-glass-moves-animated-reanimated-scrolls-itself" aria-label="Permalink to &quot;A3 · Glass moves (Animated / Reanimated / scrolls itself)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>What happens</th><th>Code</th><th>Conf.</th></tr></thead><tbody><tr><td>1</td><td>Native-driver animations change view properties without <code>invalidate</code></td><td>—</td><td>🟢</td></tr><tr><td>2</td><td>Pre-draw compares the backdrop→glass matrix with last frame → changed → invalidate</td><td><code>onPreDraw</code></td><td>🟢</td></tr><tr><td>3</td><td>Draw re-records <code>glassNode</code> with the new matrix</td><td><code>RenderNodeGlassRenderer</code></td><td>🟢</td></tr><tr><td>4</td><td>Android 7–11: the snapshot is <strong>shifted</strong> by the delta (no re-capture) until the move exceeds half the padding</td><td><code>BackdropSnapshot.draw / needsRecapture</code></td><td>🟢</td></tr></tbody></table><p><strong>Expected:</strong> blur stays locked to the world behind the glass while it moves, on every tier.</p><h3 id="a4-·-glass-touching-the-screen-edge-tab-bar" tabindex="-1">A4 · Glass touching the screen edge (tab bar) <a class="header-anchor" href="#a4-·-glass-touching-the-screen-edge-tab-bar" aria-label="Permalink to &quot;A4 · Glass touching the screen edge (tab bar)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>What happens</th><th>Conf.</th></tr></thead><tbody><tr><td>1</td><td>Sample area = glass + padding ∩ backdrop bounds, so nothing outside the screen is sampled</td><td>🟢</td></tr><tr><td>2</td><td>Blur uses <code>TileMode.CLAMP</code> at the node edge, so edge pixels repeat</td><td>🟡 (framework semantics; the Skia preview with CLAMP emulation confirms the maths)</td></tr></tbody></table><p><strong>Expected:</strong> evenly frosted to the edge, no see-through strip.</p><h3 id="a5-·-press-on-interactive-glass-liquidglassbutton" tabindex="-1">A5 · Press on interactive glass / <code>LiquidGlassButton</code> <a class="header-anchor" href="#a5-·-press-on-interactive-glass-liquidglassbutton" aria-label="Permalink to &quot;A5 · Press on interactive glass / `LiquidGlassButton`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>What happens</th><th>Code</th><th>Conf.</th></tr></thead><tbody><tr><td>1</td><td>DOWN passes through <code>dispatchTouchEvent</code> (observed, not consumed). Touch glow fades in over 120 ms; press amount animates 0→1 over 110 ms</td><td><code>TouchLightController</code>, <code>PressAnimator</code></td><td>🟢</td></tr><tr><td>2</td><td>Canvas scales to 0.965 around the centre; the backdrop sample is counter-scaled so the world doesn&#39;t move</td><td><code>LiquidGlassView.draw</code>, renderers</td><td>🟢</td></tr><tr><td>3</td><td>JS <code>onPressIn</code> arrives a moment later → <code>pressed=true</code>, already pressed, no-op</td><td><code>commitConfig</code></td><td>🟢</td></tr><tr><td>4</td><td>UP: glass stays pressed until JS sends <code>pressed=false</code>, then springs back with overshoot (420 ms)</td><td><code>PressAnimator</code></td><td>🟢</td></tr><tr><td>5</td><td>A ScrollView steals the gesture → CANCEL → light fades, spring back</td><td>—</td><td>🟡</td></tr><tr><td>6</td><td>Disabled button: no native feedback</td><td>Button passes <code>interactive={false}</code></td><td>🟢</td></tr></tbody></table><p><strong>Expected:</strong> release begins one JS round-trip after the finger lifts (usually under one frame, longer if JS is busy).</p><h3 id="a6-·-many-glass-views-stress" tabindex="-1">A6 · Many glass views (stress) <a class="header-anchor" href="#a6-·-many-glass-views-stress" aria-label="Permalink to &quot;A6 · Many glass views (stress)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Count</th><th>Auto quality (high-end 13+)</th><th>Per-frame GPU work while content moves</th></tr></thead><tbody><tr><td>1–6</td><td>HIGH (refraction + RGB split)</td><td>N blur + shader passes</td></tr><tr><td>7–12</td><td>MEDIUM (no RGB split)</td><td>N blur + shader passes</td></tr><tr><td>13+</td><td>LOW (blur only, no shader)</td><td>N blur passes</td></tr></tbody></table><p>🟢 for the switching logic. 🔴 for actual frame rates; they must be measured.</p><p><strong>Far-away animations (🟢, fixed):</strong> an invalidation inside a backdrop only redraws glass views whose sample area overlaps the changed view (old or new position). A corner spinner no longer re-blurs every glass. Check it with <code>skippedFarChanges</code> in <code>getGlassStats()</code>.</p><h3 id="a7-·-idle-screen" tabindex="-1">A7 · Idle screen <a class="header-anchor" href="#a7-·-idle-screen" aria-label="Permalink to &quot;A7 · Idle screen&quot;">​</a></h3><p>Nothing changes, so there are no invalidations and no redraws. Pre-draw listeners only run when something else triggers a frame. 🟢 <strong>Expected:</strong> zero extra battery cost when nothing moves.</p><h3 id="a8-·-navigate-away-and-back" tabindex="-1">A8 · Navigate away and back <a class="header-anchor" href="#a8-·-navigate-away-and-back" aria-label="Permalink to &quot;A8 · Navigate away and back&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>What happens</th><th>Conf.</th></tr></thead><tbody><tr><td>1</td><td>Detach: glass unbinds; the backdrop stops recording and discards its display list; renderer memory is released</td><td>🟢</td></tr><tr><td>2</td><td>Re-attach: both re-register; glass rebinds; recording is re-enabled even though it&#39;s the same backdrop object</td><td>🟢 (was a bug, fixed)</td></tr></tbody></table><h3 id="a9-·-collapsed-hidden-glass-height-0-display-none-invisible" tabindex="-1">A9 · Collapsed / hidden glass (<code>height: 0</code>, <code>display: none</code>, invisible) <a class="header-anchor" href="#a9-·-collapsed-hidden-glass-height-0-display-none-invisible" aria-label="Permalink to &quot;A9 · Collapsed / hidden glass (`height: 0`, `display: none`, invisible)&quot;">​</a></h3><p>Pre-draw skips it, so there are no redraws. 🟢 (Before the fix this looped at 60 fps forever.)</p><h3 id="a10-·-setup-mistakes" tabindex="-1">A10 · Setup mistakes <a class="header-anchor" href="#a10-·-setup-mistakes" aria-label="Permalink to &quot;A10 · Setup mistakes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mistake</th><th>Result</th><th>Conf.</th></tr></thead><tbody><tr><td>No backdrop</td><td>Frosted solid colour + one <code>LiquidGlass</code> logcat warning</td><td>🟢</td></tr><tr><td>Glass inside its backdrop</td><td>Never binds to it (no loop), solid + warning</td><td>🟢</td></tr><tr><td>Glass in a Modal, backdrop outside</td><td>Different window → solid + warning</td><td>🟢</td></tr><tr><td>Not rebuilt / Expo Go</td><td>JS fallback view + one JS warning</td><td>🟢</td></tr></tbody></table><h3 id="a11-·-android-7–11-compat" tabindex="-1">A11 · Android 7–11 (compat) <a class="header-anchor" href="#a11-·-android-7–11-compat" aria-label="Permalink to &quot;A11 · Android 7–11 (compat)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Situation</th><th>Behaviour</th><th>Conf.</th></tr></thead><tbody><tr><td>Content scrolls inside backdrop</td><td>Re-capture of a 1/4-size software drawing, at most every 32 ms (MEDIUM), with a final capture after scrolling stops</td><td>🟢</td></tr><tr><td>Images using HARDWARE bitmaps behind glass</td><td>Capture throws → solid, retried every 3 s, warning once</td><td>🟡</td></tr><tr><td>Video / map in SurfaceView</td><td>Not captured (empty)</td><td>🟢</td></tr></tbody></table><hr><h2 id="ios" tabindex="-1">iOS <a class="header-anchor" href="#ios" aria-label="Permalink to &quot;iOS&quot;">​</a></h2><h3 id="i1-·-mount" tabindex="-1">I1 · Mount <a class="header-anchor" href="#i1-·-mount" aria-label="Permalink to &quot;I1 · Mount&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>What happens</th><th>Conf.</th></tr></thead><tbody><tr><td>1</td><td><code>LiquidGlassViewComponentView</code> creates: effect view, fallback view, child container (children always above)</td><td>🟢 (code) / 🔴 (never compiled)</td></tr><tr><td>2</td><td>Props: iOS 26 → <code>UIGlassEffect</code> (regular/clear, tint, interactive). iOS 15–25 → system material picked from <code>blurRadius</code>, plus tint view and light sheen</td><td>🟡</td></tr><tr><td>3</td><td>RN applies its own border radius after us with the same value → consistent</td><td>🟢</td></tr><tr><td>4</td><td><code>GlassBackdrop</code> is a plain View; the system samples the screen itself</td><td>🟢</td></tr></tbody></table><h3 id="i2-·-press-a-liquidglassbutton" tabindex="-1">I2 · Press a <code>LiquidGlassButton</code> <a class="header-anchor" href="#i2-·-press-a-liquidglassbutton" aria-label="Permalink to &quot;I2 · Press a `LiquidGlassButton`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>iOS</th><th>Behaviour</th><th>Conf.</th></tr></thead><tbody><tr><td>26+</td><td>JS spring (0.96) + system glass response when the finger lands on the glass surface (not on the label)</td><td>🟡</td></tr><tr><td>15–25</td><td>JS spring + sheen boost</td><td>🟢</td></tr></tbody></table><h3 id="i3-·-accessibility" tabindex="-1">I3 · Accessibility <a class="header-anchor" href="#i3-·-accessibility" aria-label="Permalink to &quot;I3 · Accessibility&quot;">​</a></h3><p>Reduce Transparency on → opaque fallback, updates live via notification. Reduce Motion → effect changes don&#39;t animate. 🟢</p><h3 id="i4-·-performance" tabindex="-1">I4 · Performance <a class="header-anchor" href="#i4-·-performance" aria-label="Permalink to &quot;I4 · Performance&quot;">​</a></h3><p>UIKit renders the blur. Cost grows with the number and size of overlapping blur views; Apple advises keeping them few. Fading glass (alpha &lt; 1) renders blur incorrectly: a UIKit limitation. 🟡</p><hr><h2 id="bugs-this-trace-found-all-fixed" tabindex="-1">Bugs this trace found (all fixed) <a class="header-anchor" href="#bugs-this-trace-found-all-fixed" aria-label="Permalink to &quot;Bugs this trace found (all fixed)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Bug</th><th>Symptom it would have caused</th><th>Fix</th></tr></thead><tbody><tr><td>1</td><td>Zero-size / hidden glass never updated its &quot;last seen&quot; state</td><td>Redraw loop at 60 fps forever, draining battery</td><td><code>onPreDraw</code> skips 0-size / hidden glass</td></tr><tr><td>2</td><td>Sampling beyond the backdrop at screen edges</td><td>Tab bars / headers faded to see-through at the edge</td><td>Sample area clipped to backdrop; shader <code>uOrigin</code></td></tr><tr><td>3</td><td>Compat renderer throttled movement</td><td>Blur lagged, then snapped, while cards scrolled (Android 7–11)</td><td>Shift snapshot per frame; re-capture only past padding</td></tr><tr><td>4</td><td>Squish compensation baked into the compat capture</td><td>Background wobbled during the press spring (Android 7–11)</td><td>Compensate at draw time</td></tr><tr><td>5</td><td>Disabled button still observed touches</td><td>Disabled button squished and glowed</td><td><code>interactive={false}</code> when disabled</td></tr><tr><td>6</td><td>iOS 26 button skipped the JS spring, but system glass rarely got the touch</td><td>No press feedback on iOS 26</td><td>JS spring on iOS always; effect view touchable when interactive</td></tr><tr><td>7</td><td>Battery-saver IPC per glass per mount</td><td>Jank when many glass views mount (lists)</td><td>Cached, refreshed by broadcast</td></tr><tr><td>8</td><td>New chained RenderEffect every frame</td><td>Needless allocations / GPU layer updates</td><td>Reused while inputs are unchanged</td></tr><tr><td>9</td><td>Any change anywhere in a backdrop redrew every glass on it</td><td>Constant GPU work from a far-away spinner / Lottie</td><td>Proximity filter on the invalidated view&#39;s old + new screen rect</td></tr></tbody></table><h2 id="still-to-verify-on-a-device-highest-risk-first" tabindex="-1">Still to verify on a device (highest risk first) <a class="header-anchor" href="#still-to-verify-on-a-device-highest-risk-first" aria-label="Permalink to &quot;Still to verify on a device (highest risk first)&quot;">​</a></h2><ol><li><s>The iOS code compiles</s> ✅ now type-checked with <code>npm run check:ios</code> (real iOS SDK + RN headers). Still unverified: <code>pod install</code>, linking, running 🟡</li><li>The Android Gradle + codegen build inside a real app 🔴 (Kotlin compiles against the real android.jar; Gradle itself not run)</li><li>A RenderNode drawn in two parents (backdrop + glass) renders correctly on the RenderThread 🟡</li><li><code>onDescendantInvalidated</code> fires for scroll / animation on Android 8+ 🟡</li><li><code>RenderEffect</code> CLAMP repeats edge pixels on a RenderNode (no dark rim at node edges) 🟡</li><li>Frame rates at 1 / 6 / 12 glass on mid-range hardware 🔴. The example&#39;s Stress screen now shows native work per second (<code>getGlassStats</code>) to make this a 5-minute measurement</li></ol>',49)])])}const b=e(s,[["render",o]]);export{u as __pageData,b as default};
